-- Phong Than 2026-10-04 (content D6): Vietnamese names for servertimer-spawned NPCs that still carry GBK names.
-- Generated by scratchpad\content\gen_misc.py. servertimer.lua PTAdm_ExtTick calls PTEXT_noidung_Tick() once a
-- minute (protected), after PTAdm_EnsureNpcs of the same tick.
-- Rows { GBK name, TCVN3 name }: every PTADM_NPC_SPAWN row whose s[6] is the GBK name gets the new name in the
-- table AND on the tracked NPC (PTADM_SPAWNED[k]) in the same call - never one without the other, so EnsureNpcs
-- (GetNpcName(ni) == s[6]) keeps seeing its NPC: no duplicate. Untracked or dead rows only get the table change,
-- EnsureNpcs then spawns them with the new name. Region NPCs are renamed by ext\npcnames.lua instead.
-- Camel = template 366 next to the Bao Thuong merchants of 1002/1003/1004/1020/1021.
PTND_ROWS = {
	{ "\194\230\205\213", "L\185c \167\181" },
}
PTND_LAST = { rows = 0, npcs = 0 }

function PTND_Rename()
	local rows = 0
	local npcs = 0
	if not PTADM_NPC_SPAWN then return 0, 0 end
	local k = 1
	while PTADM_NPC_SPAWN[k] do
		local s = PTADM_NPC_SPAWN[k]
		local j = 1
		while PTND_ROWS[j] do
			local r = PTND_ROWS[j]
			if s[6] == r[1] then
				local ni = PTADM_SPAWNED and PTADM_SPAWNED[k]
				s[6] = r[2]
				rows = rows + 1
				if ni and ni > 0 and GetNpcName(ni) == r[1] then
					SetNpcName(ni, r[2])
					npcs = npcs + 1
				end
			end
			j = j + 1
		end
		k = k + 1
	end
	return rows, npcs
end

function PTEXT_noidung_Tick()
	local r, n = PTND_Rename()
	if r > 0 then
		PTND_LAST.rows = r
		PTND_LAST.npcs = n
		if PTAdm_Log then PTAdm_Log("noidung", "OK", "spawn rows renamed=" .. r .. " live npcs=" .. n) end
	end
end
